package dashboard

import (
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/shared"
)

// ── DEVDESK-139: the frame arrives in its own message ────────────────────────

func TestAFrameMovesTheFooterSpinner(t *testing.T) {
	m := feed(t, New(testConfig(), &shared.State{}), jobs.ChangedMsg{
		Runs: []jobs.Run{running(command.ViewWorkspaces, jobs.KindScan, "~/work")},
	})

	m = feed(t, m, jobs.FrameMsg{RenderedFrame: "<R1>"})

	if footer := m.RenderFooter(180); !strings.Contains(footer, "<R1>") {
		t.Errorf("the footer does not carry the new frame:\n%s", footer)
	}
	if len(m.jobs) != 1 {
		t.Errorf("the held runs = %d after a frame, want the snapshot kept", len(m.jobs))
	}
}
	return strings.TrimSpace(b.String())
}

// §3.58, poste 6: the dashboard is the screen a user is most likely to be
// looking at while a batch runs somewhere else — which is the situation D67
// made possible. It launches none of it, so what it says is D9's degraded form:
// the count, and where to look.
func TestTheFooterCountsWorkStartedElsewhere(t *testing.T) {
	m := feed(t, New(testConfig(), &shared.State{}), jobs.ChangedMsg{
		Runs: []jobs.Run{
			running(command.ViewWorkspaces, jobs.KindScan, "~/work"),
			running(command.ViewSecurity, jobs.KindScan, "inventory"),
		},
	})
	m = feed(t, m, jobs.FrameMsg{RenderedFrame: "*"})

	status := m.status()
	if want := "2 jobs running — :jobs for details"; status.Text != want {
		t.Errorf("the footer says %q, want %q", status.Text, want)
	}
	if !status.Spinner {
		t.Error("the count carries no spinner")
	}
	if !strings.Contains(m.RenderFooter(180), "jobs running") {
		t.Error("the rendered footer does not carry the line")
	}
}

// The dashboard never gets the detailed "Scanning — 3/12" form, whatever is
// running: it passes no origin because it owns no run, and naming a batch it
// did not start would claim it did.
		t.Errorf("the runs table does not show cancelled (%s):\n%s", g, m.Render())
	}
	m, _ = step(t, m, testutil.Key("right"))
	// Targets never started are skipped by the cancellation, not cancelled.
	if g := indicator.Glyph(indicator.Skipped, true); !strings.Contains(m.Render(), g) {
		t.Errorf("the targets table does not show skipped (%s):\n%s", g, m.Render())
	}
}

func TestRunningJobsWithEveryRowFilteredOutKeepTheFooterSpinner(t *testing.T) {
	m := withRuns(t, run(1, jobs.KindScan, "~/work", jobs.ItemRunning))
	m, _ = step(t, m, testutil.Key("/"))
	for _, msg := range testutil.Type("nothing-matches-this") {
		m, _ = step(t, m, msg)
	}
	status := m.status()
	if !status.Spinner || !status.Detail.IsZero() {
		t.Errorf("Spinner = %v, Detail zero = %v; want a spinner and no detail", status.Spinner, status.Detail.IsZero())
	}
	if status.Text != "1 job running" {
		t.Errorf("Text = %q, want the count", status.Text)
	}
}

