func TestFooterKeepsTheBatchProgressBesideTheRowDetail(t *testing.T) {
	m := withSnapshot(t, loadedModel(t), []jobs.Run{syncBatch()}, nil)
	m = feed(t, m, jobsFrame("SPIN"))

	running := selectRow(t, m, "devdesk").RenderFooter(200)
	for _, w := range []string{"Syncing", ftDev, "/12"} {
		if !strings.Contains(running, w) {
			t.Errorf("selected running row: footer lacks %q:\n%s", w, running)
		}
	}
	if strings.Contains(running, "SPIN") {
		t.Errorf("a row detail with a glyph must drop the spinner:\n%s", running)
	}

	idle := selectRow(t, m, "clean-repo").RenderFooter(200)
	if !strings.Contains(idle, "/12") || !strings.Contains(idle, "SPIN") {
		t.Errorf("idle row: want the progress alone, spinning:\n%s", idle)
	}
	if strings.Contains(idle, ftDev) {
		t.Errorf("idle row shows another row's detail:\n%s", idle)
	}
}

func TestScanFailureIsAnErrorThenTheCauseStaysForTheRow(t *testing.T) {
	f := actFailure(jobs.KindScan, testContext, ftDev, "scan failed — check logs", t0())
		t.Errorf("the held runs went from %d to %d on a frame", nRuns, len(m.jobs))
	}
}

func TestAFrameMovesTheFooterSpinner(t *testing.T) {
	m := running(t, loadedModel(t), jobs.KindSync, devdeskPath)

	// An idle row keeps the spinner; the running row's own dot moves instead.
	m = selectRow(t, m, "clean-repo")
	m = feed(t, m, jobs.FrameMsg{RenderedFrame: "<R1>"})

	if footer := m.RenderFooter(160); !strings.Contains(footer, "<R1>") {
		t.Errorf("the footer does not carry the new frame:\n%s", footer)
	}
}

// A frame is not a snapshot: it must not reset what the last ChangedMsg left.
func TestAFrameKeepsTheSnapshot(t *testing.T) {
	m := running(t, loadedModel(t), jobs.KindSync, devdeskPath)

	m = feed(t, m, jobs.FrameMsg{Frame: "X", RenderedFrame: "X"})

	if !m.syncing(devdeskPath) {
		t.Error("a frame made the running sync disappear from the view")
	}
	if got := len(jobs.Unfinished(m.jobs)); got != 1 {
	if !m.table.BlinkPhase() {
		t.Error("Blink=true did not turn the phase back on")
	}
	after := m.table.Items()
	if len(before) == 0 || len(before) != len(after) || &before[0] != &after[0] {
		t.Error("a frame rebuilt the rows; the phase is read at render")
	}
}

func TestAFrameStillFeedsTheFooterSpinner(t *testing.T) {
	m := withSnapshot(t, loadedModel(t), []jobs.Run{runningRun(jobs.KindScan, indRepo)}, nil)
	m = feed(t, m, jobs.FrameMsg{Frame: "ZZ", RenderedFrame: "FOOTERFRAME", Blink: true})
	if strings.Contains(m.Render(), "ZZ") {
		t.Error("the bare frame still reaches the table")
	}
	if !strings.Contains(m.RenderFooter(120), "FOOTERFRAME") {
		t.Skip("footer shows no spinner for this state; only the table side is asserted")
	}
}

}

