func TestReturnToOriginHandsTheFrameBack(t *testing.T) {
	origin := &fakeView{}
	a := runningRouter(t, origin)

	a.returnToOrigin(filebrowser.PickCancelledMsg{})

	if len(framesSeen(origin)) == 0 {
